const express = require('express');
const { HTTP } = require('cloudevents');
const crypto = require('crypto');
const { CodeBuildClient, StartBuildCommand } = require('@aws-sdk/client-codebuild');
const knex = require('knex')({ client: 'pg', connection: process.env.DATABASE_URL });

const app = express();
app.use(express.json({ type: ['application/json', 'application/cloudevents+json'] }));
const codeBuild = new CodeBuildClient({ region: 'us-west-2' });

app.post('/events/cloudevent/git-push', async (req, res) => {
  const event = HTTP.toEvent({ headers: req.headers, body: req.body });

  if (event.type === 'dev.git.push') {
    const repoIdentifier = event.subject.replace('repository:', '');

    const repo = await knex('repositories').where({ identifier: repoIdentifier }).first();
    if (!repo) {
      return res.status(404).json({ error: 'Repository not registered' });
    }

    // Verify git webhook HMAC signature using secret stored on repository record
    const signature = req.headers['x-hub-signature-256'];
    const hmac = crypto.createHmac('sha256', repo.webhookSecret);
    const expectedSig = `sha256=${hmac.update(JSON.stringify(req.body)).digest('hex')}`;

    if (!signature || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSig))) {
      return res.status(401).json({ error: 'Invalid repository webhook signature' });
    }

    const command = new StartBuildCommand({
      projectName: repo.codebuildProjectName,
      environmentVariablesOverride: [
        { name: 'BUILD_TRIGGER_SRC', value: event.source, type: 'PLAINTEXT' }
      ]
    });

    const buildOutput = await codeBuild.send(command);
    return res.json({ buildId: buildOutput.build.id });
  }

  res.status(400).json({ error: 'Unhandled event type' });
});

app.listen(9010);
